export type AppState = {
	home: string,
	backups: string,
	folders: string[],
} & Appearance;

export type Appearance = {
	palette: import("@luft/ui").Palette | null,
	typography: Typography,
	motion: Motion,
	corners: Corners,
	locale: Locale,
};

export type Corners = "rounded" | "square";

export type Entry = {
	name: string,
	path: string,
	folder: boolean,
};

export type FileIndex = {
	files: string[],
	truncated: boolean,
};

export type FilesChanged = {
	paths: string[],
};

export type Locale = {
	languages: string[],
	formats: string,
	fixed: boolean,
};

export type Motion = "full" | "reduced" | "off";

export type Stat = {
	size: number,
	modified: number,
};

export type StoreName = "settings" | "session" | "files";

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };
